let dynamicBanWords: string[] = [];

function normalizeTextForBanCheck(str: string): string {
  if (!str) return "";
  let s = str.toLowerCase();
  
  const map: Record<string, string> = {
    "0": "о", "o": "о", "о": "а",
    "1": "и", "i": "и", "й": "и", "е": "и", "ё": "и", "э": "и", "3": "и",
    "l": "л", 
    "4": "а", "a": "а", "я": "а",
    "5": "с", "s": "с", "c": "с", 
    "7": "т", "t": "т", 
    "8": "в", "b": "в", "v": "в", "w": "в",
    "y": "у", "u": "у",
    "k": "к", 
    "h": "х", "x": "х", 
    "p": "р", "r": "р", 
    "m": "м", 
    "n": "н", 
    "g": "г", 
    "d": "д",
    "z": "з", 
    "j": "и"
  };
  
  let normalized = "";
  let lastChar = "";
  for (let ch of s) {
    const mapped = map[ch] || ch;
    // Skip duplicate normalized characters (e.g. "еббать" -> "ибат")
    if (mapped !== lastChar) {
      normalized += mapped;
      lastChar = mapped;
    }
  }
  return normalized.replace(/[^а-я0-9]/g, "");
}

