  ambientPurple.addColorStop(1, "rgba(168, 85, 247, 0)");
  ctx.fillStyle = ambientPurple;
  ctx.fillRect(0, 0, width, height);

  // Global Padding/Layout
  const leftX = 45;
  let currentY = 50;

