  const canvas = createCanvas(width, height);
  const ctx = canvas.getContext("2d");

  // 1. Solid black base
  ctx.fillStyle = "#000000";
  ctx.fillRect(0, 0, width, height);

  // 2. Large purple glowing eclipse ring in the center
  //
  //
  //

  //
  //
  //
  //
  //
  //
  //
  //
  // // Double stroke

  //
  //
  //
  //
  //

