  // Subtle ambient neon glows
  const ambientGreen = ctx.createRadialGradient(200, 100, 0, 200, 100, 300);
  ambientGreen.addColorStop(0, "rgba(52, 211, 153, 0.08)");
  ambientGreen.addColorStop(1, "rgba(52, 211, 153, 0)");
