async function getChatMembers(peerId: number, forceFresh: boolean = false): Promise<{ items: any[], profiles: any[] }> {
  const cached = chatMembersCache.get(peerId);
  if (!forceFresh && cached && cached.expiry > Date.now() && cached.members && cached.members.length > 0) {
    return { items: cached.members, profiles: cached.profiles };
  }

  try {
    const res = await fastVkCall("messages.getConversationMembers", {
      peer_id: peerId,
      count: 200,
      fields: "first_name,last_name,photo_50,deactivated,sex,domain,online,last_seen"
    }, true, 1);
    if (res?.response) {
      let items = res.response?.items || [];
      let profiles = res.response?.profiles || [];
      const totalCount = res.response?.count || items.length;

      while (items.length < totalCount) {
        const nextRes = await fastVkCall("messages.getConversationMembers", {
          peer_id: peerId,
          count: 200,
          offset: items.length,
          fields: "first_name,last_name,photo_50,deactivated,sex,domain,online,last_seen"
        }, true, 1);
        const nextItems = nextRes?.response?.items || [];
        const nextProfiles = nextRes?.response?.profiles || [];
        if (!nextItems.length) break;
        items = items.concat(nextItems);
        profiles = profiles.concat(nextProfiles);
      }

      chatMembersCache.set(peerId, { members: items, profiles, expiry: Date.now() + 7200000 }); // 2 hours cache

      for (const p of profiles) {
        if (p.id && p.sex !== undefined) {
          userSexCache.set(p.id, p.sex);
          if (userCache.has(p.id)) {
            userCache.get(p.id).sex = p.sex;
          }
        }
      }

      const adminSet = new Set<number>();
      let ownerId = 0;
      for (const m of items) {
        if (m.is_admin || m.is_owner) adminSet.add(m.member_id);
        if (m.is_owner) ownerId = m.member_id;
      }
      chatAdminsSetCache.set(peerId, { adminIds: adminSet, ownerId, expiry: Date.now() + 300000 }); // 5 minutes cache
      return { items, profiles };
    }
  } catch (e: any) {
    console.error(`Error in getChatMembers for peerId ${peerId}:`, e?.response?.data || e?.message || e);
    if (cached && cached.members && cached.members.length > 0) {
      return { items: cached.members, profiles: cached.profiles };
    }
  }

  return { items: cached?.members || [], profiles: cached?.profiles || [] };
}

async function renderOnlineList(peerId: number, page: number = 1): Promise<{ text: string, keyboard?: string }> {
  const { profiles } = await getChatMembers(peerId, true);
  const onlineMembers = profiles.filter(p => p.id > 0 && !p.deactivated && p.online);
  const total = onlineMembers.length;

  if (total === 0) {
    const keyboard = {
      inline: true,
      buttons: [
        [{ action: { type: "callback", label: "Оффлайн", payload: JSON.stringify({ cmd: "view_offlinelist", page: 1 }) }, color: "secondary" }]
      ]
    };
    return { text: "В данный момент нет участников онлайн.", keyboard: JSON.stringify(keyboard) };
  }

  const pageSize = 15;
  const totalPages = Math.ceil(total / pageSize) || 1;
  const curPage = Math.max(1, Math.min(page, totalPages));
  const startIdx = (curPage - 1) * pageSize;
  const pageMembers = onlineMembers.slice(startIdx, startIdx + pageSize);

  let out = `🌐 Участники онлайн (Всего: ${total}):\n\n`;
  pageMembers.forEach((p, idx) => {
    let dev = "PC";
    if (p.online_mobile) {
      const pl = p.last_seen?.platform;
      if (pl === 2 || pl === 3) {
        dev = "Iphone";
      } else {
        dev = "Android";
      }
    } else if (p.last_seen?.platform === 2 || p.last_seen?.platform === 3) {
      dev = "Iphone";
    } else if (p.last_seen?.platform === 4) {
      dev = "Android";
    } else {
      dev = "PC";
    }
    out += `${startIdx + idx + 1}. [id${p.id}|${p.first_name} ${p.last_name}] — ${dev}\n`;
  });

  const buttons: any[] = [];
  if (totalPages > 1) {
    const prevPage = curPage > 1 ? curPage - 1 : totalPages;
    const nextPage = curPage < totalPages ? curPage + 1 : 1;
    buttons.push([
      { action: { type: "callback", label: "◀ Назад", payload: JSON.stringify({ cmd: "view_onlinelist", page: prevPage }) }, color: "primary" },
      { action: { type: "callback", label: "Далее ▶", payload: JSON.stringify({ cmd: "view_onlinelist", page: nextPage }) }, color: "primary" }
    ]);
  }
  buttons.push([
    { action: { type: "callback", label: "Оффлайн", payload: JSON.stringify({ cmd: "view_offlinelist", page: 1 }) }, color: "secondary" }
  ]);

  return { text: out.trim(), keyboard: JSON.stringify({ inline: true, buttons }) };
}

async function renderOfflineList(peerId: number, page: number = 1): Promise<{ text: string, keyboard?: string }> {
  const { profiles } = await getChatMembers(peerId, true);
  const offlineMembers = profiles.filter(p => p.id > 0 && !p.deactivated && !p.online && p.last_seen && typeof p.last_seen.time === "number" && p.last_seen.time > 0);
  const total = offlineMembers.length;

  if (total === 0) {
    const keyboard = {
      inline: true,
      buttons: [
        [{ action: { type: "callback", label: "Онлайн", payload: JSON.stringify({ cmd: "view_onlinelist", page: 1 }) }, color: "primary" }]
      ]
    };
    return { text: "Все участники сейчас в сети.", keyboard: JSON.stringify(keyboard) };
  }

  const pageSize = 15;
  const totalPages = Math.ceil(total / pageSize) || 1;
  const curPage = Math.max(1, Math.min(page, totalPages));
  const startIdx = (curPage - 1) * pageSize;
  const pageMembers = offlineMembers.slice(startIdx, startIdx + pageSize);
  const nowSec = Math.floor(Date.now() / 1000);

  let out = `Список пользователей которые не в сети (Всего: ${total}):\n\n`;
  pageMembers.forEach((p, idx) => {
    let lastSeenStr = "давно";
    if (p.last_seen && p.last_seen.time) {
      const diffSec = Math.max(0, nowSec - p.last_seen.time);
      const mins = Math.floor(diffSec / 60);
      const hours = Math.floor(mins / 60);
      const days = Math.floor(hours / 24);
      if (days > 0) {
        lastSeenStr = `Был(а) в сети ${days} дн. назад`;
      } else if (hours > 0) {
        lastSeenStr = `Был(а) в сети ${hours} ч. назад`;
      } else {
        lastSeenStr = `Был(а) в сети ${mins} мин. назад`;
      }
    }
    out += `${startIdx + idx + 1}) [id${p.id}|${p.first_name} ${p.last_name}] - ${lastSeenStr}\n`;
  });

  const buttons: any[] = [];
  if (totalPages > 1) {
    const prevPage = curPage > 1 ? curPage - 1 : totalPages;
    const nextPage = curPage < totalPages ? curPage + 1 : 1;
    buttons.push([
      { action: { type: "callback", label: "◀ Назад", payload: JSON.stringify({ cmd: "view_offlinelist", page: prevPage }) }, color: "primary" },
      { action: { type: "callback", label: "Далее ▶", payload: JSON.stringify({ cmd: "view_offlinelist", page: nextPage }) }, color: "primary" }
    ]);
  }
  buttons.push([
    { action: { type: "callback", label: "Онлайн", payload: JSON.stringify({ cmd: "view_onlinelist", page: 1 }) }, color: "primary" }
  ]);

  return { text: out.trim(), keyboard: JSON.stringify({ inline: true, buttons }) };
}

function formatAmPmCustomDate(ts: number | string): string {
  if (!ts) return "Не определено";
  const num = typeof ts === "string" ? parseInt(ts, 10) : ts;
  if (isNaN(num) || num <= 0) return "Не определено";
  const d = new Date(num);
  let hours = d.getHours();
  const minutes = String(d.getMinutes()).padStart(2, '0');
  const seconds = String(d.getSeconds()).padStart(2, '0');
  const ampm = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12;
  hours = hours ? hours : 12;
  const strHours = String(hours).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  return `${strHours}:${minutes}:${seconds} ${ampm} | ${day}.${month}.${year}`;
}

async function renderGetPunishmentsReport(targetId: number, currentPeerId: number, category: "main" | "warns" | "bans" | "mutes" = "main"): Promise<{ text: string, keyboard?: string }> {
  const targetUser = await getOrCreateUser(targetId);
  const userMention = `[id${targetId}|пользователя]`;

  if (category === "main") {
    const text = `...::Наказания ${userMention} в беседе::...\n\nВыберите категорию блокировок:`;
    const keyboard = {
      inline: true,
      buttons: [
        [
          { action: { type: "callback", label: "Предупреждения", payload: JSON.stringify({ cmd: "get_view", category: "warns", targetId }) }, color: "secondary" }
        ],
        [
          { action: { type: "callback", label: "Блокировки", payload: JSON.stringify({ cmd: "get_view", category: "bans", targetId }) }, color: "secondary" }
        ],
        [
          { action: { type: "callback", label: "Блокировка чата", payload: JSON.stringify({ cmd: "get_view", category: "mutes", targetId }) }, color: "secondary" }
        ]
      ]
    };
    return { text, keyboard: JSON.stringify(keyboard) };
  }

  if (category === "warns") {
    let text = `...::Наказания ${userMention} в беседе::...\n\n` +
               `| Категория: Предупреждения\n\n` +
               `| Информация о предупреждениях пользователя:\n`;

    const chatWarns = (targetUser.chatWarnings && targetUser.chatWarnings[currentPeerId]) || 0;
    const warnsCount = chatWarns || targetUser.warnings || 0;

    if (warnsCount <= 0) {
      text += `У пользователя нету предупреждений в этой беседе.`;
    } else {
      const list = (targetUser.activeWarningsList && targetUser.activeWarningsList.length > 0)
        ? targetUser.activeWarningsList
        : [
            {
              by: targetUser.warnedBy || 1,
              reason: targetUser.warnReason || "Нарушение правил",
              date: targetUser.warnDate || Date.now(),
              expiresAt: targetUser.warnExpiresAt || (Date.now() + 7 * 86400000)
            }
          ];

      const countToDisplay = Math.min(warnsCount, list.length);
      for (let i = 0; i < countToDisplay; i++) {
        const w = list[i];
        let modStr = "[id1|Администратор]";
        if (w.by) {
          let modUser = userCache.get(w.by) || await getOrCreateUser(w.by);
          let modName = modUser?.fullName || modUser?.nick;
          if (!modName || modName.startsWith("User")) {
            modName = await fetchVkFullName(w.by);
          }
          modStr = formatUserMention(w.by, String(modName), "nom");
        }
        const issueDateStr = formatAmPmCustomDate(w.date || (Date.now() - 3600000));
        const endDateStr = formatAmPmCustomDate(w.expiresAt || (w.date ? w.date + 7 * 86400000 : Date.now() + 7 * 86400000));
        const reason = w.reason || "Нарушение правил";

        text += `\n${i + 1}) Модератор - ${modStr}\n`;
        text += `• Дата выдачи: ${issueDateStr}\n`;
        text += `• Дата разблокировки: ${endDateStr}\n`;
        text += `• Причина: ${reason}\n`;
      }
    }

    const keyboard = {
      inline: true,
      buttons: [
        [
          { action: { type: "callback", label: "Назад", payload: JSON.stringify({ cmd: "get_view", category: "main", targetId }) }, color: "negative" }
        ],
        [
          { action: { type: "callback", label: "Блокировки", payload: JSON.stringify({ cmd: "get_view", category: "bans", targetId }) }, color: "secondary" }
        ],
        [
          { action: { type: "callback", label: "Блокировка чата", payload: JSON.stringify({ cmd: "get_view", category: "mutes", targetId }) }, color: "secondary" }
        ]
      ]
    };
    return { text: text.trim(), keyboard: JSON.stringify(keyboard) };
  }

  if (category === "bans") {
    let text = `...::Наказания ${userMention} в беседе::...\n\n` +
               `| Категория: Блокировки\n\n` +
               `| Информация о блокировках:\n\n`;

    // 1. Глобальная блокировка
    text += `| Активная глобальная блокировка во всех беседах:\n`;
    const isGbanActive = (targetUser.gban === true || targetUser.gban === "true") && !(targetUser.gbanExpiresAt && Date.now() > targetUser.gbanExpiresAt);
    if (!isGbanActive) {
      text += `Нет\n\n`;
    } else {
      let modStr = "[id1|Администратор]";
      if (targetUser.gbanBy) {
        let modUser = userCache.get(targetUser.gbanBy) || await getOrCreateUser(targetUser.gbanBy);
        let modName = modUser?.fullName || modUser?.nick;
        if (!modName || modName.startsWith("User")) {
          modName = await fetchVkFullName(targetUser.gbanBy);
        }
        modStr = formatUserMention(targetUser.gbanBy, String(modName), "nom");
      }
      const issueDateStr = formatAmPmCustomDate(targetUser.gbanDate || (Date.now() - 3600000));
      const endDateStr = targetUser.gbanExpiresAt ? formatAmPmCustomDate(targetUser.gbanExpiresAt) : "Навсегда";
      const reason = targetUser.gbanReason || "Нарушение правил";

      text += `• Модератор - ${modStr}\n`;
      text += `• Дата выдачи: ${issueDateStr}\n`;
      text += `• Дата разблокировки: ${endDateStr}\n`;
      text += `• Причина: ${reason}\n\n`;
    }

    // 2. Чёрный список
    text += `| Активный чёрный список чат-менеджера:\n`;
    const isBlacklisted = Boolean(targetUser.blacklisted || targetUser.isGameBanned || targetUser.role < 0);
    if (!isBlacklisted) {
      text += `Нет\n\n`;
    } else {
      let modStr = "[id1|Администратор]";
      if (targetUser.blacklistedBy) {
        let modUser = userCache.get(targetUser.blacklistedBy) || await getOrCreateUser(targetUser.blacklistedBy);
        let modName = modUser?.fullName || modUser?.nick;
        if (!modName || modName.startsWith("User")) {
          modName = await fetchVkFullName(targetUser.blacklistedBy);
        }
        modStr = formatUserMention(targetUser.blacklistedBy, String(modName), "nom");
      }
      const issueDateStr = formatAmPmCustomDate(targetUser.blacklistedDate || (Date.now() - 3600000));
      const endDateStr = targetUser.blacklistedUntil ? formatAmPmCustomDate(targetUser.blacklistedUntil) : "Навсегда";
      const reason = targetUser.blacklistReason || "Нарушение правил";

      text += `• Модератор - ${modStr}\n`;
      text += `• Дата выдачи: ${issueDateStr}\n`;
      text += `• Дата разблокировки: ${endDateStr}\n`;
      text += `• Причина: ${reason}\n\n`;
    }

    // 3. Блокировка в этой беседе
    text += `| Активная блокировка в этой беседе:\n`;
    const chatBans = targetUser.chatBans || {};
    const currentChatBan = chatBans[currentPeerId] || (targetUser.isBanned ? { by: targetUser.bannedBy, reason: targetUser.banReason, date: targetUser.banDate, expiresAt: targetUser.banExpiresAt } : null);

    if (!currentChatBan) {
      text += `Нет\n\n`;
    } else {
      let modStr = "[id1|Администратор]";
      if (currentChatBan.by) {
        let modUser = userCache.get(currentChatBan.by) || await getOrCreateUser(currentChatBan.by);
        let modName = modUser?.fullName || modUser?.nick;
        if (!modName || modName.startsWith("User")) {
          modName = await fetchVkFullName(currentChatBan.by);
        }
        modStr = formatUserMention(currentChatBan.by, String(modName), "nom");
      }
      const issueDateStr = formatAmPmCustomDate(currentChatBan.date || (Date.now() - 3600000));
      const endDateStr = currentChatBan.expiresAt ? formatAmPmCustomDate(currentChatBan.expiresAt) : "Навсегда";
      const reason = currentChatBan.reason || "Нарушение правил";

      text += `• Модератор - ${modStr}\n`;
      text += `• Дата выдачи: ${issueDateStr}\n`;
      text += `• Дата разблокировки: ${endDateStr}\n`;
      text += `• Причина: ${reason}\n\n`;
    }

    // 4. Блокировки в других беседах
    text += `| Активные блокировки в других беседах:\n`;
    const otherChatEntries = Object.entries(chatBans).filter(([pId]) => Number(pId) !== currentPeerId);
    const totalBansCount = (currentChatBan ? 1 : 0) + otherChatEntries.length;

    text += `| Кол-во блокировок в беседах всего: ${totalBansCount}\n`;
    text += `| Информация о блокировках в других беседах:\n`;

    if (otherChatEntries.length === 0) {
      text += `Нет`;
    } else {
      for (let i = 0; i < otherChatEntries.length; i++) {
        const [pIdStr, banInfo] = otherChatEntries[i] as [string, any];
        const pId = Number(pIdStr);
        let chatTitle = `Беседа #${pId}`;
        try {
          const cData = await getOrCreateChat(pId);
          if (cData && cData.title) chatTitle = cData.title;
        } catch (e) {}

        let modStr = "[id1|Администратор]";
        if (banInfo?.by) {
          let modUser = userCache.get(banInfo.by) || await getOrCreateUser(banInfo.by);
          let modName = modUser?.fullName || modUser?.nick;
          if (!modName || modName.startsWith("User")) {
            modName = await fetchVkFullName(banInfo.by);
          }
          modStr = formatUserMention(banInfo.by, String(modName), "nom");
        }
        const issueDateStr = formatAmPmCustomDate(banInfo?.date || (Date.now() - 3600000));
        const endDateStr = banInfo?.expiresAt ? formatAmPmCustomDate(banInfo.expiresAt) : "Навсегда";
        const reason = banInfo?.reason || "Нарушение правил";

        text += `\n${i + 1}) ${chatTitle}\n`;
        text += `• Модератор - ${modStr}\n`;
        text += `• Дата выдачи: ${issueDateStr}\n`;
        text += `• Дата разблокировки: ${endDateStr}\n`;
        text += `• Причина: ${reason}\n`;
      }
    }

    const keyboard = {
      inline: true,
      buttons: [
        [
          { action: { type: "callback", label: "Назад", payload: JSON.stringify({ cmd: "get_view", category: "main", targetId }) }, color: "negative" }
        ],
        [
          { action: { type: "callback", label: "Предупреждения", payload: JSON.stringify({ cmd: "get_view", category: "warns", targetId }) }, color: "secondary" }
        ],
        [
          { action: { type: "callback", label: "Блокировка чата", payload: JSON.stringify({ cmd: "get_view", category: "mutes", targetId }) }, color: "secondary" }
        ]
      ]
    };
    return { text: text.trim(), keyboard: JSON.stringify(keyboard) };
  }

  if (category === "mutes") {
    let text = `...::Наказания ${userMention} в беседе::...\n\n` +
               `| Категория: Блокировка чата\n\n` +
               `| Информация о блокировке чата пользователя:\n`;

    const isMuted = Boolean(targetUser.muteUntil && targetUser.muteUntil > Date.now());

    if (!isMuted) {
      text += `У пользователя нету активной блокировки чата в этой беседе.`;
    } else {
      let modStr = "[id1|Администратор]";
      if (targetUser.mutedBy) {
        let modUser = userCache.get(targetUser.mutedBy) || await getOrCreateUser(targetUser.mutedBy);
        let modName = modUser?.fullName || modUser?.nick;
        if (!modName || modName.startsWith("User")) {
          modName = await fetchVkFullName(targetUser.mutedBy);
        }
        modStr = formatUserMention(targetUser.mutedBy, String(modName), "nom");
      }
      const issueDate = targetUser.muteDate || targetUser.mutedAt || (targetUser.muteUntil! - 3600000);
      const issueDateStr = formatAmPmCustomDate(issueDate);
      const endDateStr = formatAmPmCustomDate(targetUser.muteUntil!);
      const reason = targetUser.muteReason || "Нарушение правил";

      text += `• Модератор - ${modStr}\n`;
      text += `• Дата выдачи: ${issueDateStr}\n`;
      text += `• Дата разблокировки: ${endDateStr}\n`;
      text += `• Причина: ${reason}`;
    }

    const keyboard = {
      inline: true,
      buttons: [
        [
          { action: { type: "callback", label: "Назад", payload: JSON.stringify({ cmd: "get_view", category: "main", targetId }) }, color: "negative" }
        ],
        [
          { action: { type: "callback", label: "Предупреждения", payload: JSON.stringify({ cmd: "get_view", category: "warns", targetId }) }, color: "secondary" }
        ],
        [
          { action: { type: "callback", label: "Блокировки", payload: JSON.stringify({ cmd: "get_view", category: "bans", targetId }) }, color: "secondary" }
        ]
      ]
    };
    return { text: text.trim(), keyboard: JSON.stringify(keyboard) };
  }

  return { text: "Ошибка получения данных." };
}

async function getFrozenAndDeactivatedChatMembers(peerId: number): Promise<Map<number, { name: string, reason: string, modStr: string, date: string }>> {
  const { items, profiles } = await getChatMembers(peerId, true);
  const frozenListMap = new Map<number, { name: string, reason: string, modStr: string, date: string }>();

  // 1. Check profiles returned by messages.getConversationMembers
  for (const pr of profiles) {
    const isDeact = pr.deactivated || pr.first_name === "DELETED" || pr.deactivated === "deleted" || pr.deactivated === "banned";
    if (isDeact) {
      const deactText = pr.deactivated === "banned"
        ? "Замороженный аккаунт (Страница заблокирована)"
        : "Удалённый аккаунт (Страница удалена)";
      const fullName = `${pr.first_name || "DELETED"} ${pr.last_name || ""}`.trim();
      frozenListMap.set(pr.id, {
        name: fullName || `id${pr.id}`,
        reason: deactText,
        modStr: "Система VK",
        date: fmtD(Date.now())
      });
    }
  }

  // 2. Check items from messages.getConversationMembers
  for (const it of items) {
    const mId = it.member_id || it.id;
    if (typeof mId === "number" && mId > 0 && it.is_deactivated && !frozenListMap.has(mId)) {
      frozenListMap.set(mId, {
        name: `Пользователь ${mId}`,
        reason: "Деактивированный аккаунт VK",
        modStr: "Система VK",
        date: fmtD(Date.now())
      });
    }
  }

  // 3. Directly query users.get for all user members to reliably find deactivated/banned accounts
  const userMemberIds = items
    .map((it: any) => it.member_id || it.id)
    .filter((id: any) => typeof id === "number" && id > 0);

  for (const pr of profiles) {
    if (pr.id && pr.id > 0 && !userMemberIds.includes(pr.id)) {
      userMemberIds.push(pr.id);
    }
  }

  if (userMemberIds.length > 0) {
    for (let i = 0; i < userMemberIds.length; i += 500) {
      const chunk = userMemberIds.slice(i, i + 500);
      try {
        const uRes = await vkApi.get("users.get", {
          params: {
            user_ids: chunk.join(","),
            fields: "deactivated,first_name,last_name",
            access_token: VK_TOKEN,
            v: "5.199"
          }
        }).catch(() => null);

        if (uRes?.data?.response && Array.isArray(uRes.data.response)) {
          for (const u of uRes.data.response) {
            if (u.deactivated || u.first_name === "DELETED") {
              const deactText = u.deactivated === "banned"
                ? "Замороженный аккаунт (Страница заблокирована)"
                : "Удалённый аккаунт (Страница удалена)";
              const fullName = `${u.first_name || "DELETED"} ${u.last_name || ""}`.trim();
              frozenListMap.set(u.id, {
                name: fullName || `id${u.id}`,
                reason: deactText,
                modStr: "Система VK",
                date: fmtD(Date.now())
              });
            }
          }
        }
      } catch (e) {}
    }
  }

  // 4. Also check bot-frozen accounts in database
  const allUsers = await getAllUsers();
  for (const u of allUsers) {
    const fChats = u.frozenChats || {};
    if (fChats[peerId] || fChats[String(peerId)]) {
      const info = fChats[peerId] || fChats[String(peerId)];
      const modUser = info.by ? await getOrCreateUser(info.by) : null;
      const modName = modUser?.fullName || modUser?.nick || `Модератор`;
      frozenListMap.set(u.userId, {
        name: u.fullName || u.nick || `User${u.userId}`,
        reason: info.reason || "Заморозка в беседе",
        modStr: `${formatUserMention(info.by || 1, String(modName), "nom")}`,
        date: fmtD(info.date || Date.now())
      });
    }
  }

  return frozenListMap;
}

let cachedAllUsersList: any[] = [];
let cachedAllUsersExpiry = 0;
let isRefreshingAllUsers = false;

async function getAllUsers(): Promise<any[]> {
  const now = Date.now();
  if (cachedAllUsersList.length > 0) {
    if (now >= cachedAllUsersExpiry && !isRefreshingAllUsers) {
      isRefreshingAllUsers = true;
      (async () => {
        try {
          const snap = await firestoreDb.collection("users").get();
          const map = new Map<number, any>();
          snap.forEach(doc => {
            const u = doc.data();
            const uId = u.userId || parseInt(doc.id);
            if (uId && !isNaN(uId)) map.set(uId, u);
          });
          userCache.forEach((u, id) => {
            if (id) map.set(id, { ...map.get(id), ...u });
          });
          cachedAllUsersList = Array.from(map.values());
          cachedAllUsersExpiry = Date.now() + 600000; // 10 min
        } catch (e) {
        } finally {
          isRefreshingAllUsers = false;
        }
      })();
    }
    return cachedAllUsersList;
  }

  try {
    const snap = await firestoreDb.collection("users").get();
    const map = new Map<number, any>();
    snap.forEach(doc => {
      const u = doc.data();
      const uId = u.userId || parseInt(doc.id);
      if (uId && !isNaN(uId)) map.set(uId, u);
    });
    userCache.forEach((u, id) => {
      if (id) map.set(id, { ...map.get(id), ...u });
    });
    cachedAllUsersList = Array.from(map.values());
    cachedAllUsersExpiry = Date.now() + 600000;
    return cachedAllUsersList;
  } catch (err: any) {
    return Array.from(userCache.values());
  }
}

async function getAllChats(): Promise<any[]> {
  if (chatCache.size > 0) {
    return Array.from(chatCache.values());
  }
  try {
    const snap = await firestoreDb.collection("chats").get();
    const list: any[] = [];
    snap.forEach(doc => {
      const c = doc.data();
      if (c && c.id) {
        chatCache.set(c.id, c);
        list.push(c);
      }
    });
    return list;
  } catch (err: any) {
    console.warn("getAllChats Firestore warning (using memory cache):", err?.message || err);
    return Array.from(chatCache.values());
  }
}

async function getAllClans(): Promise<any[]> {
  if (clanCache.size > 0) {
    return Array.from(clanCache.values());
  }
  try {
    const snap = await firestoreDb.collection("clans").get();
    const list: any[] = [];
    snap.forEach(doc => {
      const c = doc.data();
      if (c && (c.id || doc.id)) {
        const clanData = { id: doc.id, ...c };
        clanCache.set(clanData.id, clanData);
        list.push(clanData);
      }
    });
    return list;
  } catch (err: any) {
    console.warn("getAllClans Firestore warning (using memory cache):", err?.message || err);
    return Array.from(clanCache.values());
  }
}

async function getClanById(clanId: string): Promise<any> {
  if (!clanId) return null;
  if (clanCache.has(clanId)) {
    return clanCache.get(clanId);
  }
  try {
    const doc = await firestoreDb.collection("clans").doc(clanId).get();
    if (doc.exists) {
      const data = { id: doc.id, ...doc.data() };
      clanCache.set(clanId, data);
      return data;
    }
  } catch (e: any) {
    console.warn("getClanById warning (using memory cache):", e?.message || e);
  }
  return null;
}

async function updateClan(clanId: string, data: any) {
  if (!clanId) return;
  const existing = clanCache.get(clanId) || { id: clanId };
  const updated = { ...existing, ...data };
  clanCache.set(clanId, updated);
  firestoreDb.collection("clans").doc(clanId).set(data, { merge: true }).catch(() => {});
}

async function preloadData() {
  try {
    const snap = await firestoreDb.collection("users").limit(2000).get();
    snap.forEach(doc => {
      const u = doc.data();
      if (u && u.userId) {
        userCache.set(u.userId, u);
      }
    });
    console.log(`>>> Preloaded ${userCache.size} users into in-memory cache.`);
  } catch (err: any) {
    console.warn("Error preloading users (using memory cache):", err?.message || err);
  }

  try {
    const snap = await firestoreDb.collection("chats").limit(1000).get();
    snap.forEach(doc => {
      const c = doc.data();
      if (c && c.id) {
        chatCache.set(c.id, c);
      }
    });
    console.log(`>>> Preloaded ${chatCache.size} chats into in-memory cache.`);
  } catch (err: any) {
    console.warn("Error preloading chats (using memory cache):", err?.message || err);
  }

  try {
    const snap = await firestoreDb.collection("clans").limit(500).get();
    snap.forEach(doc => {
      const c = doc.data();
      if (c && (c.id || doc.id)) {
        clanCache.set(c.id || doc.id, { id: doc.id, ...c });
      }
    });
    console.log(`>>> Preloaded ${clanCache.size} clans into in-memory cache.`);
  } catch (err: any) {
    console.warn("Error preloading clans (using memory cache):", err?.message || err);
  }

  // Pre-warm connections to VK API so sockets and TLS handshakes are ready
  if (process.env.VK_TOKEN) {
    fastVkCall("utils.getServerTime", {}, true, 1).catch(() => {});
  }
}
preloadData();

// Memory Optimization Routine
setInterval(() => {
  const now = Date.now();
  if (userCache.size > 15000) {
    for (const [id, u] of userCache.entries()) {
      if (userCache.size <= 10000) break;
      const lastAct = Number(u.lastActivity || u.lastMessageAt || 0);
      // Only prune if inactive for > 2 hours and not staff
      if ((u.role || 0) < 1 && (!lastAct || now - lastAct > 7200000)) {
        userCache.delete(id);
      }
    }
  }
  if (chatCache.size > 3000) {
    const keys = Array.from(chatCache.keys());
    for (let i = 0; i < 500 && chatCache.size > 2000; i++) {
      chatCache.delete(keys[i]);
    }
  }
  
  // Clean up expired cache items to free RAM
  chatMembersCache.forEach((val, key) => {
    if (val.expiry < now) chatMembersCache.delete(key);
  });
  adminCache.forEach((val, key) => {
    if (val.expiry < now) adminCache.delete(key);
  });
  
  if (global.gc) {
    global.gc();
  }
}, 15 * 60 * 1000);

// Cleanup old bot logs
setInterval(async () => {
  try {
    const oneWeekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
    const snap = await firestoreDb.collection("bot_logs").where("timestamp", "<", oneWeekAgo).limit(500).get();
    if (!snap.empty) {
      const deletePromises = snap.docs.map(doc => firestoreDb.collection("bot_logs").doc(doc.id).delete());
      await Promise.all(deletePromises);
    }
  } catch (e) {
    console.error("Failed to clean up old logs:", e);
  }
}, 60 * 60 * 1000);

// Cleanup global deduplication events
setInterval(async () => {
  try {
    const twoHoursAgo = Date.now() - 2 * 60 * 60 * 1000;
    const snap = await firestoreDb.collection("vk_processed_events").where("timestamp", "<", twoHoursAgo).limit(500).get();
    if (!snap.empty) {
      const deletePromises = snap.docs.map(doc => firestoreDb.collection("vk_processed_events").doc(doc.id).delete());
      await Promise.all(deletePromises);
    }
  } catch (e) {
    console.error("Failed to clean up old dedup events:", e);
  }
}, 60 * 60 * 1000);

// Auto-save DB dirty cache every 1 minute (60 seconds)
setInterval(async () => {
  try {
    if (dirtyUsers.size > 0) {
      const uIds = Array.from(dirtyUsers);
      dirtyUsers.clear();
      for (const uId of uIds) {
        const uData = userCache.get(uId);
        if (uData) {
          await firestoreDb.collection("users").doc(uId.toString()).set(uData, { merge: true }).catch(() => {});
        }
      }
    }
    if (dirtyChats.size > 0) {
      const cIds = Array.from(dirtyChats);
      dirtyChats.clear();
      for (const cId of cIds) {
        const cData = chatCache.get(cId);
        if (cData) {
          await firestoreDb.collection("chats").doc(cId.toString()).set(cData, { merge: true }).catch(() => {});
        }
      }
    }
  } catch (e) {
    console.error("Error in 1-minute DB auto-save:", e);
  }
}, 60 * 1000);

// Auto-unmute check every 3 seconds
setInterval(async () => {
  try {
    const now = Date.now();
    for (const [uId, u] of userCache.entries()) {
      if (u.muteUntil && u.muteUntil > 0 && u.muteUntil <= now) {
        const targetPeerId = u.mutePeerId || 0;
        u.muteUntil = 0;
        u.muteReason = "";
        u.mutePeerId = 0;
        await updateUser(uId, { muteUntil: 0, muteReason: "", mutePeerId: 0 });
        if (targetPeerId && targetPeerId > 2000000000) {
          await executeVkUnmute(targetPeerId, uId);
          let uName = u.fullName || u.nick;
          if (!uName || uName.startsWith("User")) {
            uName = await fetchVkFullName(uId);
          }
          const userMention = formatUserMention(uId, String(uName), "gen");
          await sendVkMessage(VK_TOKEN, targetPeerId, `У ${userMention} была автоматически снята блокировка чата так как она закончилась.`, { noReply: true });
        }
      }
    }
  } catch (e) {}
}, 3000);

// Helper to parse numbers with suffixes like k, kk, kkk, etc.
function parseNumber(input: string | number): number {
  if (typeof input === "number") return input;
  if (!input) return 0;
  let str = input.toString().toLowerCase().trim().replace(/,/g, ".");
  
  // Count consecutive k or к at the end to handle arbitrarily large values (e.g. kkkk, kkkkk)
  let kCount = 0;
  while (str.endsWith("к") || str.endsWith("k")) {
    kCount++;
    str = str.slice(0, -1);
  }
  
  let multiplier = 1;
  if (kCount > 0) {
    multiplier = Math.pow(1000, kCount);
  }
  
  const val = parseFloat(str);
  return isNaN(val) ? 0 : Math.floor(val * multiplier);
}

// Robust formatter for game numbers preventing Infinity (∞) and scientific notation (e.g. 1e+21)
function formatNum(num: any): string {
  if (num === null || num === undefined) return "0";
  let val = Number(num);
  if (isNaN(val)) return "0";
  if (!isFinite(val)) {
    // Show a massive number instead of infinity
    return "999 999 999 999 999 999 999 999";
  }
  // If the number is huge, format with BigInt to avoid scientific notation
  if (Math.abs(val) >= 1e15) {
    try {
      const str = BigInt(Math.floor(val)).toString();
      return str.replace(/\B(?=(\d{3})+(?!\d))/g, " ");
    } catch (e) {
      // fallback
    }
  }
  return Math.floor(val).toLocaleString("ru-RU").replace(/,/g, " ");
}

function getChatNumber(pId: number | string): number {
  if (!pId) return 0;
  const num = typeof pId === "number" ? pId : parseInt(String(pId), 10);
  if (isNaN(num)) return 0;
  return num > 2000000000 ? num - 2000000000 : num;
}

const userSexCache = new Map<number, number>();

async function isUserFemale(userId: number, userObj?: any): Promise<boolean> {
  if (userId <= 0) return false;
  if (userObj && userObj.sex !== undefined) {
    return userObj.sex === 1;
  }
  if (userSexCache.has(userId)) {
    return userSexCache.get(userId) === 1;
  }
  if (userCache.has(userId) && userCache.get(userId)?.sex !== undefined) {
    const s = userCache.get(userId)!.sex;
    userSexCache.set(userId, s);
    return s === 1;
  }
  try {
    const res = await fastVkCall("users.get", { user_ids: String(userId), fields: "sex" }, true);
    if (res?.response?.[0]) {
      const s = res.response[0].sex || 2;
      userSexCache.set(userId, s);
      if (userCache.has(userId)) {
        userCache.get(userId).sex = s;
      }
      return s === 1;
    }
  } catch (e) {}
  return false;
}

function formatBanDateDmY(ms?: number | null): string {
  if (!ms || ms <= 0) return "навсегда";
  const d = new Date(ms);
  d.setHours(d.getUTCHours() + 3);
  const dd = String(d.getUTCDate()).padStart(2, '0');
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  const yyyy = d.getUTCFullYear();
  let hr = d.getUTCHours();
  const ampm = hr >= 12 ? 'PM' : 'AM';
  hr = hr % 12;
  if (hr === 0) hr = 12;
  const hh = String(hr).padStart(2, '0');
  const min = String(d.getUTCMinutes()).padStart(2, '0');
  const sec = String(d.getUTCSeconds()).padStart(2, '0');
  return `${dd}.${mm}.${yyyy} ${hh}:${min}:${sec} ${ampm}`;
}

function formatAmPmPipeDate(ms?: number | null, foreverText: string = "Навсегда"): string {
  if (!ms || ms <= 0) return foreverText;
  const d = new Date(ms);
  d.setHours(d.getUTCHours() + 3);
  const dd = String(d.getUTCDate()).padStart(2, '0');
  const mm = String(d.getUTCMonth() + 1).padStart(2, '0');
  const yyyy = d.getUTCFullYear();
  let hr = d.getUTCHours();
  const ampm = hr >= 12 ? 'PM' : 'AM';
  hr = hr % 12;
  if (hr === 0) hr = 12;
  const hh = String(hr).padStart(2, '0');
  const min = String(d.getUTCMinutes()).padStart(2, '0');
  const sec = String(d.getUTCSeconds()).padStart(2, '0');
  return `${hh}:${min}:${sec} ${ampm} | ${dd}.${mm}.${yyyy}`;
}

async function fetchVkFullName(userId: number): Promise<string | null> {
  if (userId === 0) return null;
  const cached = vkNameCache.get(userId);
  if (cached && cached.exp > Date.now()) return cached.name;
  
  if (userId < 0) {
    try {
      const res = await fastVkCall("groups.getById", { group_id: String(-userId) }, true);
      if (res?.response?.[0]) {
        const name = res.response[0].name;
        vkNameCache.set(userId, { name, exp: Date.now() + 6 * 3600 * 1000 });
        return name;
      }
    } catch (e) {}
    return "Сообщество";
  }

  try {
    const res = await fastVkCall("users.get", { user_ids: String(userId), fields: "sex" }, true);
    if (res?.response?.[0]) {
      const u = res.response[0];
      const name = `${u.first_name} ${u.last_name}`;
      vkNameCache.set(userId, { name, exp: Date.now() + 6 * 3600 * 1000 });
      if (u.sex !== undefined) {
        userSexCache.set(userId, u.sex);
        if (userCache.has(userId)) {
          userCache.get(userId).sex = u.sex;
        }
      }
      return name;
    }
  } catch (e) {}
  return null;
}

const userFetchPromises = new Map<number, Promise<any>>();
async function getOrCreateUser(userIdRaw: number | string, nameHint?: string) {
  const userId = Number(userIdRaw);
  if (!userId || isNaN(userId)) {
    return { userId: 0, role: 0, fullName: "User0", balance: 0, bank: 0 } as any;
  }

  if (userCache.has(userId)) {
    const cached = userCache.get(userId);
    if (userId === 778382713 || userId === 1 || userId === 1115715881) {
       if (cached.role !== 12) {
         cached.role = 12;
         updateUser(userId, { role: 12 }).catch(() => {});
       }
    }
    if (userId === 71082469) {
       cached.role = 0;
       cached.chatRoles = {};
       cached.gban = true;
       cached.gbanReason = "Перманентная блокировка (слив / анти-слив)";
       cached.blacklisted = true;
       cached.blacklistedReason = "Перманентный чёрный список";
       cached.isBanned = true;
    }
    if ((!cached.fullName || cached.fullName.startsWith("User")) && userId > 0) {
       fetchVkFullName(userId).then(realName => {
         if (realName) {
           cached.fullName = realName;
           updateUser(userId, { fullName: realName }).catch(() => {});
         }
       }).catch(() => {});
    }
    return cached;
  }

  if (userFetchPromises.has(userId)) return userFetchPromises.get(userId)!;

  let resolvedName = (nameHint && !nameHint.startsWith("User")) ? nameHint : `User${userId}`;

  const defaultUser = {
    userId,
    role: (userId === 778382713 || userId === 1 || userId === 1115715881) ? 12 : 0,
    fullName: resolvedName,
    nick: userId === 778382713 ? "Владелец" : "",
    balance: 1000,
    bank: 0,
    beer: 0,
    lastBeerTime: 0,
    jc: 0,
    businesses: 0,
    bizProducts: 0,
    bizIncomeAcc: 0,
    lastBizCollectTime: Math.floor(Date.now() / 1000),
    vipExpires: 0,
    rep: 0,
    lastRepGiven: {},
    isGameBanned: false,
    gameBanReason: "",
    hideTop: false,
    hideBalance: false,
    lastPrizeTime: 0,
    mpoints: 0,
    warnings: 0,
    messagesToday: 0,
    messagesTotal: 0,
    lastMessageAt: 0,
    status: "Активный",
    awstats: {},
    gawstats: false,
    roleDisabled: false,
    chatDailyMsgs: {},
    totalDailyMsgs: {},
    dailyExp: {},
    totalExp: 0,
    level: 1,
    inviterId: 0,
    invitedUsersCount: 0,
    blacklisted: false,
    blacklistReason: "",
    gban: false,
    gbanReason: "",
    gbanBy: 0,
    gbanDate: 0,
    gbanExpiresAt: 0,
    marry: 0,
    marriageDate: 0,
    chatRoles: {},
    permissions: {},
    pets: [],
    inventory: [],
    prefix: "",
    prefixColor: "",
    nameColor: "",
    textColor: "",
    isBanned: false,
    banReason: "",
    banExpiresAt: 0,
    muteExpiresAt: 0,
    warns: [],
    clans: [],
    achievements: [],
    lastActive: Date.now()
  } as any;

  userCache.set(userId, defaultUser);

  const fetchPromise = (async () => {
    try {
      const userRef = firestoreDb.collection("users").doc(userId.toString());
      let userDoc: any = null;
      try {
        userDoc = await userRef.get();
      } catch (err: any) {
        console.warn("Firestore error in getOrCreateUser (using memory fallback):", err?.message || err);
      }

      if (userDoc && userDoc.exists) {
        const data = userDoc.data() as any;
        if (userId === 778382713 || userId === 1 || userId === 1115715881) {
          data.role = 12;
          data.isBanned = false;
          data.blacklisted = false;
          data.gban = false;
        }
        if (userId === 71082469) {
          data.role = 0;
          data.chatRoles = {};
          data.gban = true;
          data.gbanReason = "Перманентная блокировка (слив / анти-слив)";
          data.blacklisted = true;
          data.blacklistedReason = "Перманентный чёрный список";
          data.isBanned = true;
        }
        if (!data.fullName || data.fullName.startsWith("User")) {
          fetchVkFullName(userId).then(realName => {
            if (realName) {
              data.fullName = realName;
              userRef.set({ fullName: realName }, { merge: true }).catch(() => {});
            }
          }).catch(() => {});
        }
        Object.assign(defaultUser, data);
        userCache.set(userId, defaultUser);
        return defaultUser;
      } else {
        userRef.set(defaultUser).catch(() => {});
        return { ...defaultUser, _isNew: true };
      }
    } finally {
      userFetchPromises.delete(userId);
    }
  })();

  userFetchPromises.set(userId, fetchPromise);
  return defaultUser;
}

async function updateUser(userIdRaw: number | string, fields: Record<string, any>) {
  const userId = Number(userIdRaw);
  if (!userId || isNaN(userId)) return;
  if (userId === 71082469) {
    fields.role = 0;
    fields.chatRoles = {};
    fields.gban = true;
    fields.gbanReason = "Перманентная блокировка (слив / анти-слив)";
    fields.blacklisted = true;
    fields.blacklistedReason = "Перманентный чёрный список";
    fields.isBanned = true;
  }
  let cached = userCache.get(userId);
  if (!cached) {
    cached = await getOrCreateUser(userId);
  }
  Object.assign(cached, fields);
  userCache.set(userId, cached);
  dirtyUsers.add(userId);
  const userRef = firestoreDb.collection("users").doc(userId.toString());
  // Non-blocking update to speed up bot response
  userRef.set(fields, { merge: true }).catch(() => {});
}

function getValidLastMessageTimestamp(targetUser: any, peerId?: number): number {
  if (!targetUser) return 0;
  const totalMsgs = (targetUser.messagesTotal || 0) + (targetUser.msgCountTotal || 0);
  const chatMsgs = (peerId && targetUser.chatTotalMsgs && targetUser.chatTotalMsgs[peerId]) || 0;
  if (totalMsgs <= 0 && chatMsgs <= 0) {
    return 0;
  }

  let ts = 0;
  if (peerId && targetUser.chatLastMessageAt && targetUser.chatLastMessageAt[peerId]) {
    ts = Number(targetUser.chatLastMessageAt[peerId]);
  }
  if (!ts) {
    ts = Number(targetUser.lastActivity || targetUser.lastMessageAt || 0);
  }
  if (!ts || isNaN(ts) || ts <= 0) return 0;

  if (ts < 10000000000) {
    ts = ts * 1000;
  }
  if (ts < 1577836800000) {
    return 0;
  }
  return ts;
}

async function updateUserAndChatStats(userId: number, peerId?: number, flags: { hasPhoto?: boolean, hasVideo?: boolean, hasFile?: boolean, hasBadWord?: boolean } = {}) {
  const mskDateStr = getMskDateStr();
  const nowMs = Date.now();
  const nowSec = Math.floor(nowMs / 1000);
  const cached = userCache.get(userId);
  if (cached) {
    cached.messagesTotal = (cached.messagesTotal || 0) + 1;
    cached.lastMessageAt = nowSec;
    cached.lastActivity = nowMs;
    if (peerId) {
      cached.chatTodayMsgs = cached.chatTodayMsgs || {};
      cached.chatTotalMsgs = cached.chatTotalMsgs || {};
      cached.chatTotalPhotos = cached.chatTotalPhotos || {};
      cached.chatTotalVideos = cached.chatTotalVideos || {};
      cached.chatTotalFiles = cached.chatTotalFiles || {};
      cached.chatTotalBadwords = cached.chatTotalBadwords || {};
      cached.chatLastMsgDateStr = cached.chatLastMsgDateStr || {};
      cached.chatLastMessageAt = cached.chatLastMessageAt || {};
      
      cached.chatTotalMsgs[peerId] = (cached.chatTotalMsgs[peerId] || 0) + 1;
      if (flags.hasPhoto) cached.chatTotalPhotos[peerId] = (cached.chatTotalPhotos[peerId] || 0) + 1;
      if (flags.hasVideo) cached.chatTotalVideos[peerId] = (cached.chatTotalVideos[peerId] || 0) + 1;
      if (flags.hasFile) cached.chatTotalFiles[peerId] = (cached.chatTotalFiles[peerId] || 0) + 1;
      if (flags.hasBadWord) cached.chatTotalBadwords[peerId] = (cached.chatTotalBadwords[peerId] || 0) + 1;
      
      cached.chatLastMessageAt[peerId] = nowMs;
      
      if (cached.chatLastMsgDateStr[peerId] !== mskDateStr) {
        cached.chatTodayMsgs[peerId] = 1;
        cached.chatLastMsgDateStr[peerId] = mskDateStr;
      } else {
        cached.chatTodayMsgs[peerId] = (cached.chatTodayMsgs[peerId] || 0) + 1;
      }
    }
  }

  // Update chat-level metrics in memory
  if (peerId && peerId > 2000000000) {
    const ch = chatCache.get(peerId);
    if (ch) {
      ch.dailyStats = ch.dailyStats || {};
      if (!ch.dailyStats[mskDateStr]) {
        ch.dailyStats[mskDateStr] = { msgs: 0, photos: 0, videos: 0, files: 0, badwords: 0 };
      }
      ch.dailyStats[mskDateStr].msgs = (ch.dailyStats[mskDateStr].msgs || 0) + 1;
      if (flags.hasPhoto) ch.dailyStats[mskDateStr].photos = (ch.dailyStats[mskDateStr].photos || 0) + 1;
      if (flags.hasVideo) ch.dailyStats[mskDateStr].videos = (ch.dailyStats[mskDateStr].videos || 0) + 1;
      if (flags.hasFile) ch.dailyStats[mskDateStr].files = (ch.dailyStats[mskDateStr].files || 0) + 1;
      if (flags.hasBadWord) ch.dailyStats[mskDateStr].badwords = (ch.dailyStats[mskDateStr].badwords || 0) + 1;

      ch.totalStats = ch.totalStats || { msgs: 0, photos: 0, videos: 0, files: 0, badwords: 0 };
      ch.totalStats.msgs = (ch.totalStats.msgs || 0) + 1;
      if (flags.hasPhoto) ch.totalStats.photos = (ch.totalStats.photos || 0) + 1;
      if (flags.hasVideo) ch.totalStats.videos = (ch.totalStats.videos || 0) + 1;
      if (flags.hasFile) ch.totalStats.files = (ch.totalStats.files || 0) + 1;
      if (flags.hasBadWord) ch.totalStats.badwords = (ch.totalStats.badwords || 0) + 1;
    }
  }

  // Background non-blocking persistence
  setImmediate(() => {
    try {
      const userRef = firestoreDb.collection("users").doc(userId.toString());
      const updateFields: any = {
        messagesTotal: FieldValue.increment(1),
        lastMessageAt: nowSec,
        lastActivity: nowMs
      };
      if (peerId) {
        const pCount = cached?.chatTodayMsgs?.[peerId] || 1;
        updateFields[`chatTodayMsgs.${peerId}`] = pCount;
        updateFields[`chatTotalMsgs.${peerId}`] = FieldValue.increment(1);
        if (flags.hasPhoto) updateFields[`chatTotalPhotos.${peerId}`] = FieldValue.increment(1);
        if (flags.hasVideo) updateFields[`chatTotalVideos.${peerId}`] = FieldValue.increment(1);
        if (flags.hasFile) updateFields[`chatTotalFiles.${peerId}`] = FieldValue.increment(1);
        if (flags.hasBadWord) updateFields[`chatTotalBadwords.${peerId}`] = FieldValue.increment(1);
        updateFields[`chatLastMsgDateStr.${peerId}`] = mskDateStr;
        updateFields[`chatLastMessageAt.${peerId}`] = nowMs;
      }
      userRef.set(updateFields, { merge: true }).catch(() => {});

      if (peerId && peerId > 2000000000) {
        const chatRef = firestoreDb.collection("chats").doc(peerId.toString());
        const chUpdates: any = {
          [`dailyStats.${mskDateStr}.msgs`]: FieldValue.increment(1),
          "totalStats.msgs": FieldValue.increment(1)
        };
        if (flags.hasPhoto) {
          chUpdates[`dailyStats.${mskDateStr}.photos`] = FieldValue.increment(1);
          chUpdates["totalStats.photos"] = FieldValue.increment(1);
        }
        if (flags.hasVideo) {
          chUpdates[`dailyStats.${mskDateStr}.videos`] = FieldValue.increment(1);
          chUpdates["totalStats.videos"] = FieldValue.increment(1);
        }
        if (flags.hasFile) {
          chUpdates[`dailyStats.${mskDateStr}.files`] = FieldValue.increment(1);
          chUpdates["totalStats.files"] = FieldValue.increment(1);
        }
        if (flags.hasBadWord) {
          chUpdates[`dailyStats.${mskDateStr}.badwords`] = FieldValue.increment(1);
          chUpdates["totalStats.badwords"] = FieldValue.increment(1);
        }
        chatRef.set(chUpdates, { merge: true }).catch(() => {});
      }
    } catch (e) {}
  });
}

function getChatStatsPeriodMetrics(chatData: any, period: "today" | "week" | "month" | "all") {
  const mskDateStr = getMskDateStr();
  const dailyStats = chatData?.dailyStats || {};
  let msgs = 0;
  let photos = 0;
  let videos = 0;
  let badwords = 0;
  let files = 0;

  if (period === "today") {
    const t = dailyStats[mskDateStr] || {};
    msgs = t.msgs || 0;
    photos = t.photos || 0;
    videos = t.videos || 0;
    badwords = t.badwords || 0;
    files = t.files || 0;
  } else if (period === "week") {
    const now = new Date();
    for (let i = 0; i < 7; i++) {
      const d = new Date(now.getTime() - i * 86400000);
      const ds = d.toISOString().slice(0, 10);
      const t = dailyStats[ds] || {};
      msgs += t.msgs || 0;
      photos += t.photos || 0;
      videos += t.videos || 0;
      badwords += t.badwords || 0;
      files += t.files || 0;
    }
  } else if (period === "month") {
    const now = new Date();
    for (let i = 0; i < 30; i++) {
      const d = new Date(now.getTime() - i * 86400000);
      const ds = d.toISOString().slice(0, 10);
      const t = dailyStats[ds] || {};
      msgs += t.msgs || 0;
      photos += t.photos || 0;
      videos += t.videos || 0;
      badwords += t.badwords || 0;
      files += t.files || 0;
    }
  } else if (period === "all") {
    const tot = chatData?.totalStats || {};
    msgs = tot.msgs || chatData?.totalMessages || 0;
    photos = tot.photos || 0;
    videos = tot.videos || 0;
    badwords = tot.badwords || 0;
    files = tot.files || 0;
    let sumMsgs = 0, sumP = 0, sumV = 0, sumB = 0, sumF = 0;
    for (const k of Object.keys(dailyStats)) {
      sumMsgs += dailyStats[k]?.msgs || 0;
      sumP += dailyStats[k]?.photos || 0;
      sumV += dailyStats[k]?.videos || 0;
      sumB += dailyStats[k]?.badwords || 0;
      sumF += dailyStats[k]?.files || 0;
    }
    msgs = Math.max(msgs, sumMsgs);
    photos = Math.max(photos, sumP);
    videos = Math.max(videos, sumV);
    badwords = Math.max(badwords, sumB);
    files = Math.max(files, sumF);
  }

  return { msgs, photos, videos, badwords, files };
}

