      if (!lobby.participants.some(p => p.id === userId)) return sendVkToast(VK_TOKEN, eventId, userId, peerId, "Вы не в игре!");

      if (lobby.amount && lobby.amount > 0) {
        await updateUser(userId, { balance: (user.balance || 0) + lobby.amount });
      }

