            "варны", "warns", "преды", "списокварнов", "банлист", "banlist", "списокбанов", "баны", "мутлист", "mutelist", "списокмутов", "муты", "онлайн", "online", "ктоонлайн", "онлайне", "оффлайн", "offline", "офлайн",
