          const upSecs = uptimeSec % 60;
          const uptimeStr = `${String(upHours).padStart(2, "0")}:${String(upMins).padStart(2, "0")}:${String(upSecs).padStart(2, "0")}`;

          const dateObj = new Date(botStartTime);
